"""Cellular-automata cave generator.

Pipeline:
  1. Seed a 60x40 grid with 45% wall noise (deterministic per seed).
  2. Run 5 smoothing iterations of the "4-5 rule":
     a cell becomes wall if >= 5 of its 8 neighbors are walls
     (out-of-bounds cells count as walls).
  3. Flood fill to find open regions; keep only the largest one,
     fill all others with wall.
"""

from __future__ import annotations

import random
from collections import deque
from typing import List, Set, Tuple

WIDTH = 60
HEIGHT = 40
WALL_RATIO = 0.45
SMOOTH_ITERATIONS = 5
RULE_THRESHOLD = 5  # becomes wall if >= 5 of 8 neighbors are walls

WALL = "#"
OPEN = "."


def generate(seed: int) -> List[List[str]]:
    """Generate a cave as a grid of chars ('#' wall, '.' open). Deterministic per seed."""
    rng = random.Random(seed)
    grid = [
        [WALL if rng.random() < WALL_RATIO else OPEN for _ in range(WIDTH)]
        for _ in range(HEIGHT)
    ]
    for _ in range(SMOOTH_ITERATIONS):
        grid = _smooth(grid)
    return _keep_largest_region(grid)


def _smooth(grid: List[List[str]]) -> List[List[str]]:
    h, w = len(grid), len(grid[0])
    new_grid = [[WALL] * w for _ in range(h)]
    for y in range(h):
        for x in range(w):
            wall_neighbors = 0
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    if dy == 0 and dx == 0:
                        continue
                    ny, nx = y + dy, x + dx
                    if not (0 <= ny < h and 0 <= nx < w) or grid[ny][nx] == WALL:
                        wall_neighbors += 1
            new_grid[y][x] = WALL if wall_neighbors >= RULE_THRESHOLD else OPEN
    return new_grid


def _regions(grid: List[List[str]]) -> List[Set[Tuple[int, int]]]:
    """Return all connected open regions (4-connectivity)."""
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    regions: List[Set[Tuple[int, int]]] = []
    for y in range(h):
        for x in range(w):
            if grid[y][x] != OPEN or seen[y][x]:
                continue
            region: Set[Tuple[int, int]] = set()
            queue = deque([(y, x)])
            seen[y][x] = True
            while queue:
                cy, cx = queue.popleft()
                region.add((cy, cx))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = cy + dy, cx + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == OPEN:
                        seen[ny][nx] = True
                        queue.append((ny, nx))
            regions.append(region)
    return regions


def _keep_largest_region(grid: List[List[str]]) -> List[List[str]]:
    regions = _regions(grid)
    if not regions:
        return [[WALL] * len(row) for row in grid]
    largest = max(regions, key=len)
    return [
        [cell if (y, x) in largest else WALL for x, cell in enumerate(row)]
        for y, row in enumerate(grid)
    ]


if __name__ == "__main__":
    import sys

    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    for row in generate(seed):
        print("".join(row))

