import random
from caves import WIDTH, HEIGHT, WALL_RATIO, WALL, OPEN, _force_border_wall, _keep_largest_region

def smooth2(grid):
    h, w = len(grid), len(grid[0])
    out = [[OPEN]*w for _ in range(h)]
    for y in range(h):
        for x in range(w):
            n = sum(1 for dy in (-1,0,1) for dx in (-1,0,1)
                    if (dy or dx) and (not (0<=y+dy<h and 0<=x+dx<w) or grid[y+dy][x+dx]==WALL))
            if grid[y][x] == WALL:
                out[y][x] = WALL if n >= 4 else OPEN
            else:
                out[y][x] = WALL if n >= 5 else OPEN
    _force_border_wall(out)
    return out

for seed in [1,7,15]:
    rng = random.Random(seed)
    g = [[WALL if rng.random()<WALL_RATIO else OPEN for _ in range(WIDTH)] for _ in range(HEIGHT)]
    _force_border_wall(g)
    for _ in range(5): g = smooth2(g)
    g = _keep_largest_region(g)
    frac = sum(r.count(OPEN) for r in g)/(WIDTH*HEIGHT)
    print(seed, round(frac,3))
